document.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const ids=['volumen','categorias','frecuencia','permanencia','geografia'];const t=TempoTools.puntosTitulares(Number($('titulares').value));const vals=[t,...ids.map(id=>$ (id).value==='x'?null:Number($(id).value))];const r=TempoTools.escala(vals);const direct=$('directo').value;const automatic=direct==='si';const large=automatic||(r&&r.granEscala);const gap=t===null;let g=automatic?'Ha identificado un supuesto de gran escala directa. Su encaje debe confirmarse; ese supuesto no depende del puntaje.':r?(r.granEscala?'El cálculo alcanza el umbral de gran escala.':'El cálculo queda por debajo del umbral de gran escala.'):'No es posible cerrar el cálculo con la información indicada.';if(direct==='nose')g+=' La posible calificación directa sigue pendiente, cualquiera que sea el puntaje.';if(direct==='no'&&r&&!r.granEscala)g+=' Este resultado depende de que no exista un supuesto directo omitido.';const signal=$('publico').value==='si'||$('sector').value==='si'||large;const d=signal?'Sus respuestas señalan una causa para revisar la designación obligatoria de un DPD. Confirme el supuesto y los requisitos del delegado.':'No hemos confirmado una causa con estas respuestas. Esto no equivale a una exención: revise su actividad y los demás supuestos legales.';show('<p class="eyebrow">Resultados separados</p><h2>Gran escala</h2><p>'+g+'</p>'+(r?'<p class="amount">'+String(r.total).replace('.',',')+' puntos</p><p>Umbral: 6 puntos. No se añade una condición de superar 1.000 personas.</p><dl>'+['Personas','Tipos de datos','Categorías','Frecuencia','Permanencia','Geografía'].map((label,i)=>'<dt>'+label+'</dt><dd>'+String(vals[i]).replace('.',',')+'</dd>').join('')+'</dl>':'<p>'+ (gap?'El texto del artículo 8 deja sin tramo expreso los valores entre 100.001 y 100.999 titulares. Esta herramienta no completa ese vacío por su cuenta; solicite una revisión del criterio aplicable.':'Complete las variables desconocidas para obtener el puntaje.')+'</p>')+'<h2>Delegado de Protección de Datos</h2><p>'+d+'</p><p>Contar con un delegado no certifica el cumplimiento de toda la organización. La modalidad externa es una alternativa de contratación, no una obligación general.</p><p>Conserve la evaluación y revísela cuando cambie el tratamiento. Este cálculo orienta; no verifica sus datos, documentos ni la correcta elección de categorías.</p>'+finish());});